--- 刷新标题和立绘
function UIActivityFashionPassDialog:RefreshDrawingAndTitle()
    local scheduleId = self.comp.activityContentId
    local scheduleVo = self.comp:GetScheduleVo(scheduleId)

    -- 立绘
    ---@type DrawingNode
    local env = CfUtils.GetLuaScr(self.BossDrawingNode, "Game.Behaviours.DrawingNode")
    if env then
        env:SetParams(scheduleVo.lobbyMode)
        env:ShowSkin()
    end

    -- 名字节点
    ---@type CommonBtnRoleNameNode
    local env = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
    if env then
        env:RefreshSelf(scheduleVo.lobbyMode, nil, nil, true, true)
    end

    -- 标题
    local title = self.comp.activityDojo.name
    CfUtils.FillText(self.TxtTitle, title)

    -- 描述
    local slogan = scheduleVo.desc
    CfUtils.FillText(self.TxtSlogan, slogan)

    -- 剩余时间
    local endTime = self.comp.activityDojo.endTime
    local leftTime = ActivityUtils.ConventLeftTimeText(endTime)
    CfUtils.FillText(self.TextTime, leftTime)
end

--- 刷新等级和经验
function UIActivityFashionPassDialog:RefreshExpAndLevel()
    -- 当前等级和经验
    local curLevel, maxLevel, curExp, curExpMax = self.comp:GetLevelAndExp()
    local isMaxLevel = self.comp:IsMaxLevel()

    CfUtils.FillText(self.TxtLvNum, string.format("LV. <size=80>%d</size>", curLevel))
    if isMaxLevel then
        CfUtils.FillText(self.TxtExpNumber, string.format("<size=40>%d</size>/%d", curExpMax, curExpMax))
    else
        CfUtils.FillText(self.TxtExpNumber, string.format("<size=40>%d</size>/%d", curExp, curExpMax))
    end

    if isMaxLevel then
        CfUtils.SetSliderPercent(self.LevelSlider.gameObject, 1)
    else
        CfUtils.SetSliderPercent(self.LevelSlider.gameObject, curExp / curExpMax)
    end
    
    -- 可领取状态
    local canGetExp = self.comp:CanGetDailyExp()
    CfUtils.SetUISwitchText(self.TextGetExp, canGetExp and 1 or 2)

    -- 领取按钮
    if canGetExp then
        SetButtonAction(self.BtnGetExp, function()
            local beforeLevel = curLevel
            self.comp:RequestGetDailyExp(function(afterLevel)
                -- 刷新等级和经验
                self:RefreshExpAndLevel()

                if beforeLevel < afterLevel then
                    -- 等级提升
                    self:RefreshRewardList()
                end
            end)
        end)
    else
        SetButtonAction(self.BtnGetExp, function()
            if isMaxLevel then
                GameUtils.Toast(localize("已经达到最大等级了"))
            else
                GameUtils.Toast(localize("今天已经不能再领取了"))
            end
        end)
    end

    -- 购买等级按钮
    if isMaxLevel then
        CfUtils.SetButtonStyle(self.BtnBuyLevel, "B18", localize("已满级"))
        SetButtonAction(self.BtnBuyLevel, function()
            GameUtils.Toast(localize("已经达到最大等级了"))
        end)
    else
        CfUtils.SetButtonStyle(self.BtnBuyLevel, "B25", localize("购买等级"))
        SetButtonAction(self.BtnBuyLevel, function()
            UIModule.OpenDialog(UIArgs(Constants.UITypeIds.UIActivityFashionPassBuyLevelDialog, { comp = self.comp }))
        end)
    end
end

--- 刷新奖励列表表头和各种领奖按钮
function UIActivityFashionPassDialog:RefreshRewardTitleAndBtns()
    CfUtils.FillText(self.TxtBaseReward, localize("基础"))
    CfUtils.FillText(self.TxtAdvanceReward, localize("豪华"))

    -- 锁头图标
    local hasPassCard = self.comp:HasBoughtPassCard()
    KTool.SetActive(self.ImgLockAdvanceReward, not hasPassCard)

    -- 锁头解锁按钮
    if hasPassCard then
        SetButtonAction(self.BtnUnlockPassCard, nil)
    else
        SetButtonAction(self.BtnUnlockPassCard, function()
            -- 购买pass卡
            self.comp:RequestBuyPassCard(function()
                self:OnBuyPassCardSuccess()
            end)
        end)
    end
    
    -- 购买pass卡按钮
    KTool.SetActive(self.BtnBuyPassCard, not hasPassCard)
    KTool.SetActive(self.BtnAlreadyHasPassCard, hasPassCard)
    if hasPassCard then
        SetButtonAction(self.BtnBuyPassCard, nil)
    else
        SetButtonAction(self.BtnBuyPassCard, function()
            -- 购买pass卡
            self.comp:RequestBuyPassCard(function()
                self:OnBuyPassCardSuccess()
            end)
        end)
    end

    -- pass卡按钮显示价格
    local product = self.comp.homeDojo:GetPassCardProduct()
    if table.count(checkTable(product.prices)) > 0 then
        -- 消耗的货币和数量
        local currency, current
        for k, v in pairs(product.prices) do
            currency = checkInt(k)
            current = checkInt(v.current)
            break
        end
        CfUtils.FillText(self.TxtBuyPassCard, tostring(current))
        CfUtils.FillImage(self.ImgBuyPassCard, goodsConfMgr:GetPhotoPathById(currency))
        CfUtils.SetActive(self.ImgBuyPassCard, true)
    else
        local priceData = CfUtils.GetPayData(product.price, product.channelProductId) or {}
        CfUtils.FillText(self.TxtBuyPassCard, string.fmt('<size=40>%1</size>%2', priceData.currencySymbol, priceData.price))
        CfUtils.SetActive(self.ImgBuyPassCard, false)
    end
    
    -- 一键领取按钮
    SetButtonAction(self.BtnOneClickGetAll, function()
        -- 一键领取
        self.comp:RequestDrawLevelReward(-1, function(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = DeepCopy(rewards) } })
            self:RefreshRewardList()
        end)
    end)
end

--- 刷新奖励列表
function UIActivityFashionPassDialog:RefreshRewardList()
    self.cellDataList = self.comp:GetRewardCellDataList()
    local maxNum = #self.cellDataList
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGroupListGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end
function UIActivityFashionPassDialog:OnGroupListGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end
    local luaIndex = index + 1

    local cellData = self.cellDataList[luaIndex]
    if cellData.lastSpan then
        -- 空占位节点
        local cell = loopListView:NewListViewItem("Cell2")
        return cell
    else
        -- 小组节点
        local cell = loopListView:NewListViewItem("Cell1")
        local LB_cell = GetLuaBehaviour(cell.gameObject, CellLuaPath)
        if not cell.IsInitHandlerCalled then
            cell.IsInitHandlerCalled = true
            LB_cell:Init()
        end
        ---@type UIActivityFashionPassRewardEntry
        local LT_cell = LB_cell.Env
        LT_cell:SetComp(self.comp)
        LT_cell:SetLuaIndex(luaIndex)
        LT_cell:SetCellData(cellData)
        LT_cell:SetClickDrawCB(Bind(self, self.RefreshRewardList))
        return cell
    end
end

--- 购买pass卡的sdk回调
function UIActivityFashionPassDialog:OnEventSdkEventHandler_(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then

        local product = self.comp.homeDojo:GetPassCardProduct()
        if parameters.productId == product.channelProductId then
            -- update passType
            self:OnBuyPassCardSuccess()
        end
    end
end

function UIActivityFashionPassDialog:OnBuyPassCardSuccess()
    self.comp.homeDojo.bought = 1
    self:RefreshRewardList()
    self:RefreshRewardTitleAndBtns()
end

function UIActivityFashionPassDialog:OnBuyLevelSuccess()
    print("OnBuyLevelSuccess")
    self:RefreshExpAndLevel()
    self:RefreshRewardList()
end

return UIActivityFashionPassDialog
